import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class DefaultKeyedValues_removeValue_TriageGen1Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_LastIndex_NoRebuild() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);
        int lastIndex = keyedValues.getItemCount() - 1;

        // Act
        keyedValues.removeValue(lastIndex);

        // Assert
        assertEquals(1, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
        assertEquals(1.0, keyedValues.getValue(0).doubleValue(), 0.001);
    }

    @Test
    public void testRemoveValue_MiddleIndex_TriggersRebuild() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);
        keyedValues.addValue("C", 3.0);

        // Act: Remove index 1 ("B")
        // Since 1 < current size (3) after removal (size becomes 2), rebuildIndex is called
        keyedValues.removeValue(1);

        // Assert
        assertEquals(2, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
        assertEquals(3.0, keyedValues.getValue(0).doubleValue(), 0.001); // Error in logic? No, index 0 is A, index 1 is C
        assertEquals("C", keyedValues.getKey(1));
        assertEquals(3.0, keyedValues.getValue(1).doubleValue(), 0.001);
    }

    @Test
    public void testRemoveValue_FirstIndex_TriggersRebuild() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);

        // Act
        keyedValues.removeValue(0);

        // Assert
        assertEquals(1, keyedValues.getItemCount());
        assertEquals("B", keyedValues.getKey(0));
        assertEquals(2.0, keyedValues.getValue(0).doubleValue(), 0.001);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveValue_InvalidIndex_ThrowsException() {
        // Arrange
        keyedValues.addValue("A", 1.0);

        // Act
        keyedValues.removeValue(5);
    }

    @Test
    public void testRemoveValue_EmptyList_ThrowsException() {
        // Act & Assert
        try {
            keyedValues.removeValue(0);
        } catch (IndexOutOfBoundsException e) {
            // Expected
        }
    }
}
